class string_buf
{
public:
  unsigned long long *data;
  int ref_count;
  int char_length;
  int block_length;
  int max_blocks;
};

class stringx
{
protected:
  char *chars;
  string_buf *my_buf;

public:
  void lock();

  inline char &operator[](int i)
  {
    lock();
    if (i < 0)
      i += length();
    return chars[i];
  }

  inline const char operator[](int i) const
  {
    if (i < 0)
      i += length();
    return chars[i];
  }

  inline int size() const
  {
    return my_buf->char_length;
  }

  inline int length() const
  {
    return size();
  }
};

class NamesMenu
{
public:
  static void ReplaceBadCharacters(stringx &tmp);
};

void NamesMenu::ReplaceBadCharacters(stringx &tmp)
{
  for(int i=0; i<tmp.length(); i++)
  {
    char c = tmp[i];
    if(!(c >= 'A' && c <= 'Z') && !(c >= 'a' && c <= 'z') &&
      !(c >= '0' && c <= '9') && c != ' ' && c!='(' && c!= ')')
      tmp[i] = '#';
  }
}
